(function(){
  if (window.__laplaceInstalled__) return;
  window.__laplaceInstalled__ = true;
  var canvas = document.getElementById('cv');
  var ctx = canvas.getContext('2d');
  var bSlider = document.getElementById('bSlider'), bVal = document.getElementById('bVal');
  var iSlider = document.getElementById('iSlider'), iVal = document.getElementById('iVal');
  var lSlider = document.getElementById('lSlider'), lVal = document.getElementById('lVal');
  var tSlider = document.getElementById('tSlider'), tVal = document.getElementById('tVal');
  var out = document.getElementById('out');
  var playBtn = document.getElementById('playBtn');
  var flowDir = 1, flow = 0;
  window.simState = { B: 0.5, I: 5, L: 0.2, theta: 90, F: 0.5, dir: 1 };
  function draw(){
    var B = parseFloat(bSlider.value), I = parseFloat(iSlider.value);
    var L = parseFloat(lSlider.value), theta = parseFloat(tSlider.value);
    var F = B * I * L * Math.sin(theta * Math.PI / 180);
    window.simState.B = B; window.simState.I = I; window.simState.L = L;
    window.simState.theta = theta; window.simState.F = F;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 1; ctx.strokeRect(0.5, 0.5, canvas.width - 1, canvas.height - 1);
    var cy = 190, cx = 210;
    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(60, cy); ctx.lineTo(660, cy); ctx.stroke();
    ctx.fillStyle = '#94a3b8'; ctx.font = '12px sans-serif'; ctx.textAlign = 'left';
    ctx.fillText('B', 60, cy - 8);
    ctx.strokeStyle = '#64748b'; ctx.lineWidth = 2;
    for (var gx = 90; gx <= 630; gx += 60) {
      ctx.beginPath(); ctx.moveTo(gx, cy - 18); ctx.lineTo(gx, cy - 2);
      ctx.moveTo(gx, cy - 18); ctx.lineTo(gx - 5, cy - 12); ctx.moveTo(gx, cy - 18); ctx.lineTo(gx + 5, cy - 12); ctx.stroke();
    }
    ctx.fillStyle = '#334155'; ctx.font = '12px sans-serif'; ctx.textAlign = 'left';
    ctx.fillText('الحقل B (أفقي نحو اليمين)', 60, cy + 20);
    var ang = theta * Math.PI / 180;
    var half = 46 + L * 240;
    var ax = cx - half * Math.cos(ang), ay = cy - half * Math.sin(ang);
    var bx = cx + half * Math.cos(ang), by = cy + half * Math.sin(ang);
    ctx.strokeStyle = '#dc2626'; ctx.lineWidth = 5;
    ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(bx, by); ctx.stroke();
    flow += 0.05 * flowDir;
    var fl = flow % 20;
    var dArrow = (L > 0.05) ? fl / 20 : 0.5;
    var dpx = ax + (bx - ax) * dArrow, dpy = ay + (by - ay) * dArrow;
    var nx = -Math.sin(ang) * flowDir, ny = Math.cos(ang) * flowDir;
    ctx.fillStyle = '#f59e0b';
    ctx.beginPath(); ctx.moveTo(dpx + nx * 9, dpy + ny * 9);
    ctx.lineTo(dpx - nx * 3 - Math.cos(ang) * 7 * flowDir, dpy - ny * 3 - Math.sin(ang) * 7 * flowDir);
    ctx.lineTo(dpx - nx * 3 + Math.cos(ang) * 7 * flowDir, dpy - ny * 3 + Math.sin(ang) * 7 * flowDir);
    ctx.fill();
    ctx.fillStyle = '#dc2626'; ctx.font = 'bold 13px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('ناقل AB (I = ' + I.toFixed(1) + ' A)', (ax + bx) / 2, (ay + by) / 2 - 14);
    ctx.fillStyle = '#0f172a'; ctx.textAlign = 'center';
    ctx.fillText('θ = ' + theta + '°', cx + (Math.cos(ang)) * 60, cy - Math.sin(ang) * 60 - 12);
    var fScale = F / 2;
    var fH = fScale * 60;
    ctx.strokeStyle = '#16a34a'; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.moveTo(560, cy); ctx.lineTo(560, cy - fH); ctx.stroke();
    ctx.fillStyle = '#16a34a';
    ctx.beginPath(); ctx.moveTo(560, cy - fH); ctx.lineTo(552, cy - fH + 12); ctx.lineTo(568, cy - fH + 12); ctx.fill();
    ctx.fillStyle = '#15803d'; ctx.font = 'bold 13px sans-serif';
    ctx.fillText('F = ' + F.toFixed(3) + ' N', 560, cy - fH - 10);
    bVal.textContent = B.toFixed(1); iVal.textContent = I.toFixed(1);
    lVal.textContent = L.toFixed(2); tVal.textContent = theta + '°';
    out.textContent = 'F = B.I.L.sinθ = ' + B.toFixed(1) + ' × ' + I.toFixed(1) + ' × ' + L.toFixed(2) + ' × sin' + theta + '° = ' + F.toFixed(3) + ' N';
    window.simState.time = (window.simState.time || 0) + 0.05;
  }
  function loop(){ draw(); requestAnimationFrame(loop); }
  playBtn.addEventListener('click', function(){ flowDir = -flowDir; window.simState.dir = flowDir; });
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  loop();
})();
